<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    background: linear-gradient(160deg, #eef2ff 0%, #f8fafc 45%, #ecfeff 100%);
    color: #0f172a;
    min-height: 100vh;
  }

  .app {
    max-width: 1120px;
    margin: 0 auto;
    padding: 44px 24px 72px;
  }

  .app-header h1 {
    font-size: 27px;
    letter-spacing: -0.02em;
    font-weight: 800;
  }

  .subtitle {
    color: #64748b;
    font-size: 14px;
    margin-top: 6px;
  }

  .add-form {
    display: flex;
    gap: 10px;
    margin-top: 20px;
    flex-wrap: wrap;
  }

  #new-card {
    flex: 1 1 260px;
    max-width: 440px;
    padding: 11px 14px;
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    font-size: 14px;
    font-family: inherit;
    background: #ffffff;
    color: #0f172a;
    transition: border-color .15s ease, box-shadow .15s ease;
  }
  #new-card::placeholder { color: #94a3b8; }
  #new-card:focus {
    outline: none;
    border-color: #6366f1;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, .18);
  }

  #add-card {
    padding: 11px 22px;
    border: none;
    border-radius: 10px;
    background: linear-gradient(135deg, #6366f1, #8b5cf6);
    color: #ffffff;
    font-size: 14px;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    box-shadow: 0 4px 12px rgba(99, 102, 241, .35);
    transition: transform .12s ease, box-shadow .12s ease, filter .12s ease;
  }
  #add-card:hover { filter: brightness(1.07); transform: translateY(-1px); }
  #add-card:active { transform: translateY(0); box-shadow: 0 2px 6px rgba(99, 102, 241, .3); }

  .board {
    display: grid;
    grid-template-columns: repeat(3, minmax(230px, 1fr));
    gap: 20px;
    align-items: start;
    margin-top: 30px;
  }

  .column {
    background: rgba(255, 255, 255, .78);
    border: 1px solid #e2e8f0;
    border-radius: 16px;
    padding: 14px;
    min-height: 340px;
    transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;
  }
  .column.drag-over {
    border-color: #6366f1;
    background: #eef2ff;
    box-shadow: 0 0 0 3px rgba(99, 102, 241, .15);
  }

  .column-head {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 4px 6px 13px;
  }

  .dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
  .dot-todo  { background: #f59e0b; }
  .dot-doing { background: #6366f1; }
  .dot-done  { background: #10b981; }

  .column-head h2 {
    font-size: 13px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .07em;
    color: #334155;
  }

  .count {
    margin-left: auto;
    background: #e2e8f0;
    color: #475569;
    font-size: 12px;
    font-weight: 700;
    min-width: 24px;
    height: 22px;
    padding: 0 8px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .cards {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-height: 140px;
  }

  .cards:empty::before {
    content: "No cards yet";
    display: block;
    text-align: center;
    color: #94a3b8;
    font-size: 13px;
    padding: 30px 0;
    border: 1.5px dashed #d7dee8;
    border-radius: 12px;
  }

  .card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 12px 14px;
    font-size: 14px;
    line-height: 1.4;
    box-shadow: 0 1px 2px rgba(15, 23, 42, .05);
    cursor: grab;
    word-break: break-word;
    transition: box-shadow .15s ease, transform .15s ease, border-color .15s ease, opacity .15s ease;
  }
  .card:hover {
    box-shadow: 0 6px 16px rgba(15, 23, 42, .10);
    transform: translateY(-1px);
    border-color: #cbd5e1;
  }
  .card.dragging {
    opacity: .55;
    transform: rotate(1.5deg) scale(.98);
    cursor: grabbing;
  }

  .card-title { flex: 1; }

  .card-del {
    flex-shrink: 0;
    width: 24px;
    height: 24px;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: #94a3b8;
    font-size: 17px;
    line-height: 1;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background .12s ease, color .12s ease;
  }
  .card-del:hover { background: #fee2e2; color: #dc2626; }

  .footer-note {
    margin-top: 26px;
    text-align: center;
    color: #94a3b8;
    font-size: 12.5px;
  }

  .sr-only {
    position: absolute;
    width: 1px; height: 1px;
    padding: 0; margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
  }

  @media (max-width: 820px) {
    .board { grid-template-columns: 1fr; }
    .column { min-height: 180px; }
  }
</style>
</head>
<body>
<main class="app">
  <header class="app-header">
    <h1>Kanban Board</h1>
    <p class="subtitle">Drag cards between columns &mdash; everything is saved locally in your browser.</p>
    <form id="add-form" class="add-form" autocomplete="off">
      <label for="new-card" class="sr-only">New card title</label>
      <input id="new-card" type="text" placeholder="What needs doing?" maxlength="200">
      <button id="add-card" type="submit">Add card</button>
    </form>
  </header>

  <section class="board" aria-label="Kanban board">
    <div class="column" id="col-todo" data-column="todo">
      <div class="column-head">
        <span class="dot dot-todo" aria-hidden="true"></span>
        <h2>To Do</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </div>

    <div class="column" id="col-doing" data-column="doing">
      <div class="column-head">
        <span class="dot dot-doing" aria-hidden="true"></span>
        <h2>Doing</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </div>

    <div class="column" id="col-done" data-column="done">
      <div class="column-head">
        <span class="dot dot-done" aria-hidden="true"></span>
        <h2>Done</h2>
        <span class="count">0</span>
      </div>
      <div class="cards"></div>
    </div>
  </section>

  <p class="footer-note">Tip: press Enter in the input to quickly add a card.</p>
</main>

<script>
(function () {
  "use strict";

  var STORAGE_KEY = "kanban-board-v1";
  var COLUMNS = ["todo", "doing", "done"];

  var colEls = {
    todo: document.getElementById("col-todo"),
    doing: document.getElementById("col-doing"),
    done: document.getElementById("col-done")
  };

  var input = document.getElementById("new-card");
  var addForm = document.getElementById("add-form");

  var draggedId = null;

  /* ---------- State ---------- */

  function emptyState() {
    return { todo: [], doing: [], done: [] };
  }

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return emptyState();
      var parsed = JSON.parse(raw);
      var s = emptyState();
      COLUMNS.forEach(function (col) {
        if (Array.isArray(parsed[col])) {
          s[col] = parsed[col]
            .filter(function (item) { return item && typeof item.title === "string" && item.title.length > 0; })
            .map(function (item) {
              return { id: typeof item.id === "string" && item.id ? item.id : uid(), title: item.title };
            });
        }
      });
      return s;
    } catch (err) {
      return emptyState();
    }
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (err) { /* storage unavailable (e.g. some file:// contexts) */ }
  }

  function uid() {
    return "card-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 9);
  }

  var state = loadState();

  /* ---------- Mutations ---------- */

  function findCard(id) {
    for (var i = 0; i < COLUMNS.length; i++) {
      var col = COLUMNS[i];
      for (var j = 0; j < state[col].length; j++) {
        if (state[col][j].id === id) return { col: col, index: j };
      }
    }
    return null;
  }

  function addCard(rawTitle) {
    var title = (rawTitle || "").trim();
    if (!title) return false;
    state.todo.push({ id: uid(), title: title });
    saveState();
    render();
    return true;
  }

  function removeCard(id) {
    var loc = findCard(id);
    if (!loc) return;
    state[loc.col].splice(loc.index, 1);
    saveState();
    render();
  }

  function moveCard(id, toCol) {
    var loc = findCard(id);
    if (!loc || loc.col === toCol) return;
    var moved = state[loc.col].splice(loc.index, 1)[0];
    state[toCol].push(moved);
    saveState();
    render();
  }

  /* ---------- Rendering ---------- */

  function createCardEl(card) {
    var el = document.createElement("div");
    el.className = "card";
    el.setAttribute("draggable", "true");
    el.dataset.id = card.id;

    var title = document.createElement("span");
    title.className = "card-title";
    title.textContent = card.title;

    var del = document.createElement("button");
    del.type = "button";
    del.className = "card-del";
    del.textContent = "\u00D7";
    del.setAttribute("aria-label", "Delete card");
    del.addEventListener("click", function (e) {
      e.stopPropagation();
      removeCard(card.id);
    });

    el.appendChild(title);
    el.appendChild(del);

    el.addEventListener("dragstart", onDragStart);
    el.addEventListener("dragend", onDragEnd);

    return el;
  }

  function render() {
    COLUMNS.forEach(function (name) {
      var col = colEls[name];
      var container = col.querySelector(".cards");
      container.innerHTML = "";
      state[name].forEach(function (card) {
        container.appendChild(createCardEl(card));
      });
      col.querySelector(".count").textContent = String(state[name].length);
    });
  }

  /* ---------- Drag & drop ---------- */

  function onDragStart(e) {
    var cardEl = e.currentTarget;
    draggedId = cardEl.dataset.id;
    cardEl.classList.add("dragging");
    if (e.dataTransfer) {
      e.dataTransfer.effectAllowed = "move";
      try { e.dataTransfer.setData("text/plain", draggedId); } catch (err) {}
    }
  }

  function onDragEnd(e) {
    e.currentTarget.classList.remove("dragging");
    draggedId = null;
    clearDropHints();
  }

  function clearDropHints() {
    COLUMNS.forEach(function (name) {
      colEls[name].classList.remove("drag-over");
    });
  }

  COLUMNS.forEach(function (name) {
    var col = colEls[name];

    col.addEventListener("dragenter", function (e) {
      e.preventDefault();
      col.classList.add("drag-over");
    });

    col.addEventListener("dragover", function (e) {
      e.preventDefault();
      if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
      col.classList.add("drag-over");
    });

    col.addEventListener("dragleave", function (e) {
      if (!col.contains(e.relatedTarget)) {
        col.classList.remove("drag-over");
      }
    });

    col.addEventListener("drop", function (e) {
      e.preventDefault();
      col.classList.remove("drag-over");
      var id = null;
      try {
        id = e.dataTransfer ? e.dataTransfer.getData("text/plain") : null;
      } catch (err) { /* synthetic events may lack a working DataTransfer */ }
      if (!id) id = draggedId;
      if (id) moveCard(id, name);
      draggedId = null;
    });
  });

  /* ---------- Add form ---------- */

  addForm.addEventListener("submit", function (e) {
    e.preventDefault();
    if (addCard(input.value)) {
      input.value = "";
      input.focus();
    }
  });

  /* ---------- Init ---------- */

  render();
})();
</script>
</body>
</html>
